#!/usr/bin/env python3
"""Plant Disease AI final Windows application source.

The former App package modules and translation catalogs are embedded below so
this file remains the single source delivery entry point. Models, their YAML
configuration, and reusable inference code remain in the repository's Models
and Evaluation folders and are not duplicated here.
"""
from __future__ import annotations

