if os.environ.get("PLANT_DISEASE_PROJECT_ROOT"):
    PROJECT_ROOT = Path(os.environ["PLANT_DISEASE_PROJECT_ROOT"]).resolve()
elif getattr(sys, "frozen", False):
    PROJECT_ROOT = Path(sys.executable).resolve().parent.parent
