class _EmbeddedFinder(importlib.abc.MetaPathFinder, importlib.abc.Loader):
    def find_spec(self, fullname, path=None, target=None):
        record = _EMBEDDED_MODULES.get(fullname)
        if record is None:
            return None
        return importlib.util.spec_from_loader(fullname, self, is_package=record["package"])

    def create_module(self, spec):
        return None

    def exec_module(self, module: ModuleType) -> None:
        record = _EMBEDDED_MODULES[module.__name__]
        synthetic = PROJECT_ROOT / "App" / record["relative"]
        module.__file__ = str(synthetic)
        if record["package"]:
            module.__path__ = [str(synthetic.parent)]
        exec(compile(record["source"], str(synthetic), "exec"), module.__dict__)


sys.meta_path.insert(0, _EmbeddedFinder())

