from utils.platform import append_pi_system_packages, configure_pi_low_memory

append_pi_system_packages()
configure_pi_low_memory()


def _config(crop: str):
    from utils.config import apply_platform_overrides, load_config
    return apply_platform_overrides(load_config(crop=crop, project_root=PROJECT_ROOT))


def _emit_status(payload) -> None:
    text = json.dumps(payload, ensure_ascii=False)
    result_path = os.environ.get("PLANT_DISEASE_TEST_RESULT")
    if result_path:
        Path(result_path).write_text(text, encoding="utf-8")
    if sys.stdout is not None:
        print(text)


def run_application(crop: str) -> int:
    from desktop_app.app import run_app
    return run_app(crop=crop)


def run_ui_smoke_test(crop: str, timeout_ms: int = 15000) -> int:
    os.environ.setdefault("QT_QPA_PLATFORM", "offscreen")
    from PySide6.QtCore import QTimer
    from PySide6.QtWidgets import QApplication
    from desktop_app.ui.main_window import MainWindow

    application = QApplication.instance() or QApplication(sys.argv[:1])
    window = MainWindow(_config(crop))
    window.show()
    QTimer.singleShot(timeout_ms, application.quit)
    result = application.exec()
    _emit_status({"ui_started": True, "crop": crop, "exit_code": result})
    return result


def run_ml_self_test() -> int:
    import numpy as np
    from PIL import Image
    from inference.explainable_predictor import ExplainablePredictor

    results = []
    with tempfile.TemporaryDirectory(prefix="plant-disease-ai-test-") as temp_dir:
        image_path = Path(temp_dir) / "synthetic_leaf.png"
        array = np.zeros((320, 320, 3), dtype=np.uint8)
        array[..., 1] = 150
        array[80:240, 80:240, 0] = 90
        Image.fromarray(array).save(image_path)

        for crop in ("grape", "tomato"):
            predictor = ExplainablePredictor(
                _config(crop), gradcam_output_root=Path(temp_dir) / "gradcam" / crop
            )
            result = predictor.predict_with_gradcam(image_path)
            overlay = Path(result.overlay_path) if result.overlay_path else None
            if overlay is None or not overlay.exists():
                raise RuntimeError(f"Grad-CAM output missing for {crop}")
            results.append({
                "crop": crop,
                "class": result.predicted_class,
                "confidence": result.confidence,
                "weights": str(predictor.weights_path),
                "gradcam": True,
            })
    _emit_status({"self_test": "passed", "results": results})
    return 0


def parse_args():
    parser = argparse.ArgumentParser(description="Plant Disease AI desktop application")
    parser.add_argument("--crop", choices=("grape", "tomato"), default="grape")
    parser.add_argument("--self-test", action="store_true", help=argparse.SUPPRESS)
    parser.add_argument("--smoke-ui", action="store_true", help=argparse.SUPPRESS)
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    if args.self_test:
        return run_ml_self_test()
    if args.smoke_ui:
        return run_ui_smoke_test(args.crop)
    return run_application(args.crop)


if __name__ == "__main__":
    raise SystemExit(main())
